<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\unit\Features\OAuth\Client;

use Civi\Lughauth\Features\Access\Tenant\Domain\Gateway\TenantQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\Tenant\Domain\Tenant;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\Gateway\TenantConfigQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\TenantConfig;
use Civi\Lughauth\Features\Access\TenantConfig\Domain\TenantConfigDynamicRegistrationPolicyOptions;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientCommandRepositoryGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\Gateway\TrustedClientQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClient;
use Civi\Lughauth\Features\OAuth\Client\Domain\DcrRegistrationRules;
use Civi\Lughauth\Features\OAuth\Client\Domain\DynamicClientRequest;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\DynamicClientAdapter;
use Civi\Lughauth\Features\OAuth\Client\Infrastructure\Driven\TrustedClientFinder;
use Civi\Lughauth\Shared\Security\SecretDigester;
use PHPUnit\Framework\TestCase;

final class DynamicClientAdapterUnitTest extends TestCase
{
    private ?TrustedClient $stored = null;

    public function testRulesComeFromTheTenantConfig(): void
    {
        $config = $this->createStub(TenantConfig::class);
        $config->method('getDynamicRegistrationPolicy')->willReturn(TenantConfigDynamicRegistrationPolicyOptions::TOKEN_REQUIRED);
        $config->method('getDcrAllowedGrantTypes')->willReturn('["authorization_code","password"]');
        $config->method('getDcrAllowedAuthMethods')->willReturn(null);
        $config->method('isAllowPasswordGrant')->willReturn(true);

        $rules = $this->adapter($config)->registrationRules('tenant-a');

        self::assertSame(DcrRegistrationRules::TOKEN_REQUIRED, $rules->policy);
        self::assertSame(['authorization_code', 'password'], $rules->allowedGrantTypes);
        self::assertSame(['client_secret_basic', 'private_key_jwt', 'none'], $rules->allowedAuthMethods);
        self::assertTrue($rules->allowPasswordGrant);
    }

    public function testUnknownTenantOrMissingConfigDisablesRegistration(): void
    {
        self::assertSame(DcrRegistrationRules::DISABLED, $this->adapter(null)->registrationRules('tenant-a')->policy);
        self::assertSame(DcrRegistrationRules::DISABLED, $this->adapter(null)->registrationRules('nowhere')->policy);
    }

    public function testRegisteredClientIsOwnedByTheTenantAndManagedOnlyFromIt(): void
    {
        $adapter = $this->adapter(null);
        $request = new DynamicClientRequest(['https://app.example.com/cb'], grantTypes: ['authorization_code', 'refresh_token']);

        $adapter->create('tenant-a', 'dyn-client', 'secret', 'reg-token', $request);

        self::assertSame('uid-a', $this->stored?->getTenant()?->uid());
        self::assertTrue($this->stored->isEnabled(), 'A registered client must be usable');
        self::assertSame('["authorization_code","refresh_token"]', $this->stored->getGrantTypesJson());
        self::assertSame('dyn-client', $adapter->findByClientIdAndToken('tenant-a', 'dyn-client', 'reg-token')?->clientId);
        self::assertNull($adapter->findByClientIdAndToken('tenant-b', 'dyn-client', 'reg-token'));
        self::assertNull($adapter->findByClientIdAndToken('tenant-a', 'dyn-client', 'wrong-token'));
        self::assertNull($adapter->update('tenant-b', 'dyn-client', 'reg-token', $request));
        self::assertFalse($adapter->delete('tenant-b', 'dyn-client', 'reg-token'));
    }

    private function adapter(?TenantConfig $config): DynamicClientAdapter
    {
        $writer = $this->createStub(TrustedClientCommandRepositoryGateway::class);
        $writer->method('create')->willReturnCallback(fn (TrustedClient $client): TrustedClient => $this->stored = $client);
        $writer->method('findOneByUid')->willReturnCallback(fn (): ?TrustedClient => $this->stored);
        $writer->method('findOneForUpdateByUid')->willReturnCallback(fn (): ?TrustedClient => $this->stored);

        $tenants = $this->createStub(TenantQueryRepositoryGateway::class);
        $tenants->method('findOneByName')->willReturnCallback(function (string $name): ?Tenant {
            $uid = ['tenant-a' => 'uid-a', 'tenant-b' => 'uid-b'][$name] ?? null;
            if ($uid === null) {
                return null;
            }
            $tenant = $this->createStub(Tenant::class);
            $tenant->method('uid')->willReturn($uid);
            return $tenant;
        });
        $configs = $this->createStub(TenantConfigQueryRepositoryGateway::class);
        $configs->method('findOneByTenant')->willReturnCallback(
            static fn (TenantRef $tenant): ?TenantConfig => $tenant->uid() === 'uid-a' ? $config : null
        );

        return new DynamicClientAdapter(
            $writer,
            new TrustedClientFinder($this->createStub(TrustedClientQueryRepositoryGateway::class), $tenants),
            $configs,
            new SecretDigester(['p1' => 'pepper-one'], 'p1'),
        );
    }
}
